import json
import sys
import time
import os

def load_state(state_file):
    if os.path.exists(state_file):
        with open(state_file, 'r') as f:
            return json.load(f)
    return []

def save_state(state_file, state):
    with open(state_file, 'w') as f:
        json.dump(state, f)

def evaluate_expression(expr, vars_dict):
    try:
        return eval(expr, {'__builtins__': None}, vars_dict)
    except:
        return 0

def main():
    if len(sys.argv) != 4:
        print("Usage: python run_jobs.py <JOBS_FILE> <STATE_FILE> <RATE>", file=sys.stderr)
        sys.exit(1)

    jobs_file = sys.argv[1]
    state_file = sys.argv[2]
    rate = int(sys.argv[3])

    with open(jobs_file, 'r') as f:
        jobs_data = json.load(f)

    vars_dict = jobs_data['vars']
    jobs = jobs_data['jobs']
    state = load_state(state_file)
    last_start_time = 0.0

    for job in jobs:
        if job['id'] in state:
            continue

        start_time = time.time()
        value = evaluate_expression(job['expr'], vars_dict)
        print(f"{job['id']} {value}")

        sys.stdout.flush()

        state.append(job['id'])
        save_state(state_file, state)

        if last_start_time > 0 and time.time() - last_start_time < 1.0 / rate:
            time.sleep(1.0 / rate - (time.time() - last_start_time))
        last_start_time = time.time()

    sys.exit(0)

if __name__ == "__main__":
    main()
